import { runQpdf } from './qpdf';

/** Adds password protection to a PDF via qpdf's AES-256 encryption — the same
 * password is used as both the user (open) and owner (permissions) password,
 * which is what "protect this PDF with a password" means for most people. */
export async function protectPdf(file: File, password: string): Promise<Blob> {
  const bytes = new Uint8Array(await file.arrayBuffer());
  const outBytes = await runQpdf(bytes, ['--encrypt', password, password, '256', '--', '{in}', '{out}']);
  return new Blob([outBytes], { type: 'application/pdf' });
}
