import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Lock } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import UploadBox from '@/components/tools/pdf-to-jpg/UploadBox';
import PasswordField from '@/components/tools/pdf-security/PasswordField';
import ProcessResult from '@/components/tools/pdf-security/ProcessResult';
import SetupGate from '@/components/tools/pdf-security/SetupGate';
import { usePersistentState } from '@/hooks/usePersistentState';
import { protectPdf } from '@/lib/pdf/protect';

const ProtectPdf: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('protect-pdf:file', null);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [blob, setBlob] = useState<Blob | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setBlob(null);
    setError(null);
  }, [file, password, confirmPassword]);

  const mismatch = confirmPassword.length > 0 && password !== confirmPassword;
  const canGenerate = !!file && password.length > 0 && password === confirmPassword;

  const handleGenerate = () => {
    if (!file || !canGenerate) return;
    setError(null);
    setIsProcessing(true);
    protectPdf(file, password)
      .then((result) => {
        setBlob(result);
        setIsProcessing(false);
      })
      .catch((err: Error) => {
        setError(err.message || "Couldn't protect this PDF");
        setIsProcessing(false);
      });
  };

  const fileName = file ? `${file.name.replace(/\.pdf$/i, '') || 'document'}-protected.pdf` : 'protected.pdf';

  return (
    <ToolLayout
      title="Protect PDF"
      description="Add password protection to a PDF with AES-256 encryption — entirely in your browser, nothing is uploaded anywhere."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <>
            <PasswordField
              label="Password"
              value={password}
              onChange={setPassword}
              placeholder="Choose a password"
              autoComplete="new-password"
            />
            <div>
              <PasswordField
                label="Confirm password"
                value={confirmPassword}
                onChange={setConfirmPassword}
                placeholder="Re-enter the password"
                autoComplete="new-password"
              />
              {mismatch && <p className="text-xs text-destructive mt-1.5">Passwords don't match.</p>}
            </div>
          </>
        )}

        <SetupGate>
          <ProcessResult
            hasFile={!!file}
            blob={blob}
            fileName={fileName}
            isProcessing={isProcessing}
            processingLabel="Encrypting…"
            error={error}
            canGenerate={canGenerate}
            generateLabel="Protect PDF"
            generateIcon={<Lock className="w-4 h-4" />}
            onGenerate={handleGenerate}
          />
        </SetupGate>
      </div>
    </ToolLayout>
  );
};

export default ProtectPdf;
